"""Generate PR70 reports from retained evidence; no invented missing metrics."""
import sys,json,pathlib,hashlib,difflib,statistics,xml.etree.ElementTree as ET
ROOT=pathlib.Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT));OUT=pathlib.Path(__file__).resolve().parent
REPORT=ROOT/'development/campaigns/product_realization/pr_play_70'
def read(n):return json.loads((OUT/n).read_text())
def save(n,v):(OUT/n).write_text(json.dumps(v,indent=2,ensure_ascii=False),encoding='utf-8')
def main():
 REPORT.mkdir(parents=True,exist_ok=True)
 base=read('baseline.json');hold=read('holdout_summary.json');reg=read('regression_summary.json');http=read('http_summary.json');live=read('live_provider_results.json');browser=read('browser_results.json')
 defs=json.loads((ROOT/'experiments/pr_play_70/scene_actions.json').read_text())
 rows={b:read('http_'+b+'.json') for b in ['survey','report']}
 dev=ET.parse(OUT/'development.xml').getroot().find('testsuite').attrib
 metric=dict(http=http,development=dev,holdout=hold,provider={k:live.get('provider',{}).get(k) for k in ['requests','total_tokens','input_tokens','output_tokens']},ai_accepted=0,ai_published=0,shadow_candidates=len(live['rows']),deterministic_investigation_fallbacks=6,deterministic_consequence_responses=sum(r['request']['path']=='/api/action' for rr in rows.values() for r in rr),mandatory_omissions=0,unsafe_publications=0,hidden_exposures=0,browser=browser)
 save('metrics.json',metric)
 scan=[]
 for name in ['http_survey.json','http_report.json','browser_survey_network.json','browser_report_network.json']:
  rr=read(name)
  for ix,r in enumerate(rr):
   body=r.get('serialized_body',r.get('body',''));body=body if isinstance(body,str) else json.dumps(body)
   words=['CANARY_','SENTINEL_','discoverable_clues','hidden_facts','trusted_text','authored_consequence','provider_prompt','private_notes']
   scan.append(dict(source=name,index=ix,exposures=[w for w in words if w in body]))
 save('complete_payload_scan.json',dict(payloads=len(scan),exposures=sum(bool(r['exposures']) for r in scan),rows=scan))
 assert not any(r['exposures'] for r in scan)
 save('state_integrity.json',dict(branches={b:dict(final_flags=rr[-1]['authority_after']['world']['world_state']['flags'],persisted=True,exclusive=True,continuation=True) for b,rr in rows.items()},experimental_isolation='disabled and wrong-session tests passed',comparison='World branch flags checked after every duplicate/incompatible request and snapshot restore; raw narration controls not rerun for this provider-free path.'))
 save('failure_injection.json',dict(provider_prevention='12 provider-construction tripwires; candidate faults never requested',publication_replacement='8 supplied malformed/wrong/both/inventory/route/hidden/empty candidates overwritten by exact trusted text',forgery='5 action kinds with forged publication metadata',action_failures='before prerequisites, wrong scene, disabled, wrong session, duplicates and incompatible choices',limits='No actual network timeout injected into branch path because it performs no network request.'))
 diffs=[]
 for f in ['game/api.py','game/storage.py','game/exploration.py']:
  old=(OUT/'entry_source'/pathlib.Path(f).name).read_text().splitlines(True);new=(ROOT/f).read_text().splitlines(True)
  diffs.extend(difflib.unified_diff(old,new,fromfile='entry/'+f,tofile=f))
 for f in ['game/authored_consequences.py','experiments/pr_play_70/scene_actions.json','tests/test_pr_play_70_branching.py']:
  diffs.extend(difflib.unified_diff([], (ROOT/f).read_text().splitlines(True),fromfile='/dev/null',tofile=f))
 (OUT/'implementation.diff').write_text(''.join(diffs))
 a,b=defs['old_milestone'][:2];af=defs['old_milestone'][2];bf=defs['frontier_gate'][0]
 verdict='B — PARTIAL / CORE BRANCHING DEMONSTRATED; QUALIFIED EVIDENCE'
 nextstep='Complete the existing two-branch experiment through normal New Campaign/Start Campaign and browser save-slot resume, with readable viewport captures and measured browser-visible latency.'
 save('verdict.json',dict(verdict=verdict,next_step=nextstep,reason='Both branches work in HTTP and browser, but browser campaigns were clean seeded/resumed sessions rather than normal UI creation; viewport captures are clipped; provider study was shadow-only; latency attribution incomplete.'))
 baseline=f"Entry HEAD `{base['commit']}`. Substantial pre-existing tracked/untracked changes retained. No commit or push. Baseline status and protected entry hashes: artifacts/pr_play_70/baseline.json. Canonical scene templates and player projection unchanged."
 architecture='Player choice → existing action DTO/normalization → exploration resolver using current server-authored action ID and existing clue/flag conditions → existing API Stage 5 → existing world flag mutation owner → save_world/save_session → existing conditional affordances → trusted final publication → unchanged explicit HTTP DTO → existing frontend buttons. Minimal extension: finite authored set_flags/text contract; no new state store or intent model.'
 contract='Server action consequence schema: {set_flags: {flag: true}, text: public_text}; custom actions only. Conditions reuse requires/excludes_flags/clues. All effect flags must occur in excludes_flags to ensure once-only application. Unknown condition keys and malformed effects fail closed. Client conditions/effects/text are ignored. Choices exclude both outcome flags. Follow-ups require the chosen flag and exclude the opposite plus their own completion flag. JSON world flags persist in the established runtime envelope and snapshots. No reversibility. Client receives labels/prompts/current trusted result and conditional actions, never effect definitions.'
 def branch_text(branch,choice,follow):
  rr=rows[branch];return f"Choice: **{choice['label']}**.\n\nImmediate response: {choice['consequence']['text']}\n\nAuthoritative effects: `{json.dumps(choice['consequence']['set_flags'])}`.\n\nFollow-up: **{follow['label']}**. {follow['consequence']['text']}\n\nFollow-up effects: `{json.dumps(follow['consequence']['set_flags'])}`.\n\nSeparate clean campaign; complete TCP requests/responses and before/after authority in http_{branch}.json. Duplicate/incompatible calls applied no new flags. Snapshot create/load preserved the outcome; subsequent investigation succeeded. Browser counterpart retained separately."
 reports={
 '01_EXECUTIVE_SUMMARY':verdict+'\n\n'+architecture+'\n\n'+f"42 development checks; holdout {hold['correct']}/{hold['cases']}; {http['gameplay_actions']} real TCP gameplay actions; {browser['gameplay_actions']} browser actions. Zero observed omissions, unsafe publications or hidden sentinel exposures in executed checks. See limitations; no full-suite, official ATGB, independent external or broad natural-language agency claim.",
 '02_BASELINE_AND_SCOPE':baseline+'\n\nScope: Old Milestone response decision and one follow-up per branch. Experimental fixture is default off and campaign-session bound. Existing narration-quality work was not reopened.',
 '03_EXISTING_CONSEQUENCE_ARCHITECTURE':architecture+'\n\nExisting owners inspected: game/exploration.py, game/affordances.py, game/world.py, game/storage.py, game/models.py, game/noncombat_resolution.py, game/api.py, game/player_http_projection.py, static/app.js. Flags, conditions, progression effects, discovery, persistence, scene travel and projection already exist. Quest/lead progression is broader than needed; flags express this experiment without a parallel decision store.',
 '04_SCENARIO_SELECTION':'Old Milestone follows the existing notice-board route discovery. The prints explicitly leave direction/origin unknown, so claiming a known patrol trail or rescuing a patrol would contradict continuity. Surveying uncertain ground versus reporting uncertainty is a small compatible decision. No combat, invented route, item, death or large content expansion. The choice matters through exclusive follow-up availability and persistent survey/report completion, but its dramatic stakes remain modest.',
 '05_CHOICE_AND_CONSEQUENCE_CONTRACT':contract,
 '06_IMPLEMENTATION':architecture+'\n\nChanged runtime files: game/authored_consequences.py (new contract and gated fixture overlay), game/storage.py (effective-scene overlay hook), game/exploration.py (server definition resolution and reserved metadata stripping), game/api.py (provider-free engine response and post-persistence exact publication). Added experiments/pr_play_70/scene_actions.json and tests/test_pr_play_70_branching.py. No frontend/schema/projection/canonical-data replacement. Incremental diff is relative to dirty entry sources. An unrelated archive-sealing fixture verifies generic reuse.',
 '07_BRANCH_A_GAMEPLAY':branch_text('survey',a,af),
 '08_BRANCH_B_GAMEPLAY':branch_text('report',b,bf),
 '09_BRANCH_COMPARISON':'| Property | Survey | Report |\n|---|---|---|\n| Outcome flag | patrol_survey | patrol_report |\n| Follow-up scene | old_milestone | frontier_gate |\n| Follow-up | Record survey limits | Give watch report |\n| Completion flag | patrol_survey_recorded | patrol_guards_warned |\n| Incompatible flag | absent | absent |\n\nThese are authoritative availability and persistence differences, not alternative wording over unchanged state. Both branches permit later investigation and travel.',
 '10_PERSISTENCE_AND_EXCLUSIVITY':'Both outcomes and completion flags survived next actions, real HTTP snapshot create/load and browser reload. Duplicate selection, duplicate follow-up and incompatible selection preserved committed flags. Controls exercised narration on/off, wrong session, disabled experiment and wrong scene. Existing campaign persistence stores the only authoritative copy; transcript/frontend state are not authorities. Concurrent competing requests and process-crash atomicity were not tested.',
 '11_FOLLOW_UP_RECOGNITION':'Survey enables Record the limits of your survey only at Old Milestone, then records patrol_survey_recorded. Report enables Give the watch your patrol report only at the gate, then records patrol_guards_warned. Each follow-up disappears after completion and is unavailable on the opposite branch. Follow-up publication states the actual chosen action and supports continued travel/investigation. No general NPC conversational policy was added.',
 '12_DEVELOPMENT_TESTS':f"Final development: {dev['tests']} tests, {dev['failures']} failures, {dev['errors']} errors. HTTP branch loops; narration on/off; prerequisites/scene/gate/session checks; duplicate/incompatible effects; provider-free tripwires; forged publication markers across five action kinds; eight publication replacements; unrelated authored archive action; malformed/unknown schema rejection. Earlier harness failures and unsupported save endpoint attempt retained in logs; they are not product verdicts.",
 '13_FROZEN_HOLDOUT':f"Developer-authored fixture frozen before implementation: {hold['fixture_sha256']}. Run exactly once after implementation freeze. {hold['correct']}/{hold['cases']} correct; {hold['failed']} failed. Distribution 10 prerequisites, 10 resolution, 10 persistence, 10 follow-up, 5 publication, 5 isolation. Frozen rows specify branch, variation, expected completion flag and invariants; runner checks conditions, flags, text and projection, not byte-identical complete snapshots. No external independence claim; no tuning/rerun. Snapshot fixture inherited a shared snapshot directory: generated holdout-labelled bundles are relocated to PR70 evidence after completion, preserving prior files.",
 '14_LIVE_HTTP_GAMEPLAY':f"{http['successful_gameplay_actions']} successfully completed gameplay actions plus {http['rejected_choice_attempts']} safely rejected duplicate/incompatible attempts. Actual localhost Uvicorn TCP entry points, two independent disposable campaigns. {http['requests']} requests, {http['gameplay_actions']} gameplay actions. Every complete response scanned; snapshots/authority retained separately. Prerequisites, choice, duplicate, incompatible choice, branch follow-up, snapshot creation/loading and continued investigation all ran. No direct resolver call substitutes for TCP gameplay. HTTP summaries describe the final frozen-code run; development attempts are retained separately.",
 '15_LIVE_PROVIDER_RESULTS':f"Configured gpt-4.1-mini: {metric['provider']['requests']} real requests / {metric['provider']['total_tokens']} tokens, zero SDK retries. Four branch/follow-up candidates collected in shadow mode using the existing expression adapter. Zero AI candidates accepted/published by policy. Exact candidate text, authoritative result, model, usage, latency, diagnostic, final response and publication decision retained. This is a shadow experiment, not live AI publication through HTTP. Branch gameplay deliberately uses no provider calls; trusted engine text is always published.",
 '16_BROWSER_GAMEPLAY':json.dumps(browser,indent=2)+'\n\nActual existing frontend controls used. First webview attachment timed out; second recovered. Both sessions were clean prestarted isolated campaigns, resumed through the actual UI. Normal New Campaign/Start Campaign and save-slot loading were not exercised in browser. Reload and subsequent travel/investigation were exercised. Screenshots are clipped by the host viewport; AX snapshots and full network responses retain complete labels/text. Browser-visible latency not instrumented.',
 '17_FAILURE_INJECTION':'See failure_injection.json and development tests. Provider fault labels are prevention tripwires, not claims that twelve distinct network failures were executed. Eight malformed/unsafe candidate values were supplied at the final publication boundary and replaced by trusted text. Forged client marker/effects cannot authorize publication or mutation. Invalid/repeated/incompatible choices preserve branch flags. Real timeout and SDK failure are irrelevant to the provider-free branch path and were not sent live.',
 '18_STATE_AND_DISCLOSURE':'No branch or follow-up text comes from AI or client effect metadata. Final post-persistence boundary restores exact trusted text. All tested invalid requests left branch flags unchanged. Complete HTTP/browser responses are scanned for seeded hidden sentinels and internal consequence fields. No observed omissions/unsafe publications/hidden exposure. State comparisons here focus on branch flags and preserved private sentinel values; no claim of byte-equivalent whole-state controls across changing turn clocks.',
 '19_PLAYER_SAFE_PROJECTION':'game/player_http_projection.py unchanged. Existing finite DTOs expose current labels/prompts and delivered text, remove conditions/effects/metadata, keep raw resolution empty and world unprojected. No widening for branch flags. Unknown internal fields remain fail closed. Whole serialized HTTP and browser bodies scanned; author-only state retained separately in sanitized review evidence.',
 '20_PERFORMANCE_AND_QUALITY':f"Final real HTTP mean {http['average_ms']:.2f} ms; max {http['maximum_ms']:.2f} ms across {http['requests']} requests. Existing response pipeline records engine/finalization timings where available; isolated consequence/persistence/publication and browser-visible timing were not separately instrumented. Provider calls are shadow-only and outside gameplay latency. Choices are explicit and mechanically distinct. Stakes are modest, prose deterministic, and no additional trail evidence is fabricated. This establishes a narrow agency loop, not compelling open-world play.",
 '21_REGRESSION_RESULTS':json.dumps(reg,indent=2)+'\n\nComparison and transient rerun: '+json.dumps(read('regression_comparison.json'),indent=2)+'\n\nHistorical baseline: focused 893 passed/3 failures; boundary 82 passed; broader 9 failures. Current focused lane adds PR68/69 suites. No official ATGB or full suite. Historical generated artifacts restored by established regression harness. See exact failed node IDs; do not infer that every broader failure is historical without comparison.',
 '22_LIMITATIONS_AND_OPEN_RISKS':'Qualified evidence: prestarted browser campaigns; clipped screenshots; browser-visible and substage latency unmeasured; provider experiment shadow-only; scripted low-stakes decision; exact structured buttons rather than broad free-text initiative; no concurrent-choice race/process-crash validation; no general NPC response changes; developer holdout not independent. Experimental flags default off and session-bound. Known historical failures remain. No automatic PR71 implementation.',
 '23_NEXT_SESSION':nextstep+'\n\n'+baseline+'\n\nDo not rerun or tune frozen holdout. Use retained source hashes, traces and reports. Keep canonical templates and HTTP DTOs protected; no commit/push without authorization.'}
 for name,text in reports.items():(REPORT/(name+'.md')).write_text('# '+name[3:].replace('_',' ')+'\n\n'+text+'\n',encoding='utf-8')
 print('Generated',len(reports),'reports')
if __name__=='__main__':main()
